"use strict";
window.CampaignLogisticsUI=(()=>{
 const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
 function controls(host,s,act,readOnly=false){
  host.querySelector('.advanced-logistics')?.remove();if(!s)return;if(readOnly){const note=el('details');note.className='advanced-logistics';note.append(el('summary','Logistics history inspection'),el('p','Supply markers show the inspected time. Return to current time to issue logistics decisions.'));host.append(note);return;}const box=el('details');box.className='advanced-logistics';box.append(el('summary',s.logistics?'Advanced logistics | '+Object.values(s.logistics.routes).map(r=>r.status).join(', '):'Optional advanced logistics'));
  const button=(text,type,data={},disabled=false)=>{const b=el('button',text);b.disabled=readOnly||disabled;b.onclick=()=>act(type,data);box.append(b);};
  if(!s.logistics){if(s.plan||!s.supplyProfile){box.append(el('p','Choose this option at the start of a new operation, before issuing orders.'));}else{const select=el('select');select.setAttribute('aria-label','Logistics condition');for(const [value,label]of [['normal','Routine supply with transport return'],['roadblock','Authored road blockage during delivery'],['threat','Authored threat requiring escort']]){const o=el('option',label);o.value=value;select.append(o);}const rear=el('input');rear.type='checkbox';rear.disabled=!s.supplyProfile.rear||s.supplyProfile.rear.available===false;rear.setAttribute('aria-label','Include rear-area supply convoy');const label=el('label','Include rear-area supply convoy');label.prepend(rear);box.append(label);box.append(select,el('p','Two cargo slots, one repair team and one escort. Repairs take 20 minutes; escort preparation takes 10 minutes. Conditions are authored gameplay, not simulated combat.'));const b=el('button','Enable advanced logistics');b.disabled=readOnly;b.onclick=()=>act('logistics:enable',{challenge:select.value,rear:rear.checked});box.append(b);}}
  else{if(s.rearSupply){const r=s.rearSupply;box.append(el('p',r.network.hubName+' to forward depot: '+r.status+' | '+r.network.km.toFixed(1)+' km. '+r.network.travelMinutes+' minutes travel, 30 minutes receipt.'));}box.append(el('p','Repair teams available: '+s.logistics.engineersAvailable+' | Escorts available: '+s.logistics.escortsAvailable));for(const [route,r]of Object.entries(s.logistics.routes)){const number=route==='M14'?14:route==='M15'?15:Number(Object.keys(s.supplyProfile.routes)[0]),name=window.PANZER_SITUATION_LIBRARY?.find(d=>d.situation.number===number)?.situation.title||route;box.append(el('strong',name+': '+r.status));if(r.status==='blocked')button('Repair '+name+' route (20 min)','logistics:repair',{route},!!r.repairAt||!s.logistics.engineersAvailable);if(r.status==='threatened')button('Escort '+name+' convoy (10 min)','logistics:escort',{route},!!r.escort||!s.logistics.escortsAvailable);}
   for(const t of s.trips||(s.transport?[s.transport]:[])){if(t.status==='held'&&t.resumeStatus==='transit'&&t.route!=='mixed'){const key=t.route==='M14'?14:t.route==='M15'?15:Object.keys(s.supplyProfile.routes)[0];button('Use alternate road','logistics:reroute',{trip:t.id||'transport'},!s.supplyProfile.routes[key]?.detour);}if(t.status==='held'&&t.resumeStatus!=='returning')button('Recall '+(t.id||'transport'),'logistics:recall',{trip:t.id||'transport'});if(t.recalled&&t.status==='complete')button('Redispatch '+(t.id||'transport'),'logistics:redispatch',{trip:t.id||'transport'});}
  }const number=Number(Object.keys(s.supplyProfile?.routes||{})[0]);if(number){const link=el('a','View rear supply network');link.href='index.html?supplySituation='+number;box.append(link);}host.append(box);
 }
 return{controls};
})();
